const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const chiangMai = ee.Geometry.Point([98.9, 18.8]);
  const buffer = chiangMai.buffer(20000); // 20km buffer around city center

  const marchStart = '2024-03-01';
  const marchEnd = '2024-03-31';
  const mayStart = '2024-05-01';
  const mayEnd = '2024-05-31';

  // 2. Data Acquisition - MODIS Terra Monthly AOD
  const marchCol = ee.ImageCollection('MODIS/061/MOD08_M3')
    .filterDate(marchStart, marchEnd)
    .filterBounds(buffer);

  const mayCol = ee.ImageCollection('MODIS/061/MOD08_M3')
    .filterDate(mayStart, mayEnd)
    .filterBounds(buffer);

  const marchSize = marchCol.size().getInfo();
  const maySize = mayCol.size().getInfo();

  console.log(`March 2024 Images: ${marchSize}`);
  console.log(`May 2024 Images: ${maySize}`);

  if (marchSize === 0 || maySize === 0) {
    console.log("Missing data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Extract AOD values
  const marchImg = marchCol.first();
  const mayImg = mayCol.first();

  // Use AOD_550_Dark_Target_Deep_Blue_Combined_Mean band
  const aodBand = 'Aerosol_Optical_Depth_Land_Ocean_Mean';

  // Check pixel counts
  const marchCount = marchImg.select(aodBand).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 10000,
    maxPixels: 1e9
  }).get(aodBand).getInfo();

  const mayCount = mayImg.select(aodBand).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 10000,
    maxPixels: 1e9
  }).get(aodBand).getInfo();

  console.log(`March valid pixels: ${marchCount}`);
  console.log(`May valid pixels: ${mayCount}`);

  if (marchCount === 0 || mayCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Mean AOD values (scaled by 0.001)
  const marchAOD = marchImg.select(aodBand).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 10000,
    maxPixels: 1e9
  }).get(aodBand).getInfo();

  const mayAOD = mayImg.select(aodBand).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 10000,
    maxPixels: 1e9
  }).get(aodBand).getInfo();

  // Scale the values (MODIS AOD has scale factor of 0.001)
  const marchScaled = marchAOD * 0.001;
  const mayScaled = mayAOD * 0.001;

  // 5. Validation & Final Answer
  console.log(`March 2024 AOD: ${marchScaled.toFixed(4)}`);
  console.log(`May 2024 AOD: ${mayScaled.toFixed(4)}`);

  if (marchAOD === null || mayAOD === null || 
      isNaN(marchScaled) || isNaN(mayScaled) ||
      marchScaled < 0 || mayScaled < 0 || 
      marchScaled > 5 || mayScaled > 5) {
    console.log("Invalid AOD values detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (marchScaled > mayScaled) {
    console.log("March 2024 had higher AOD than May 2024.");
    console.log("<answer>A</answer>");
  } else {
    console.log("March 2024 did not have higher AOD than May 2024.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
